Craft.EvolutionAPI=(()=>{
 const pause=ms=>new Promise(r=>setTimeout(r,ms));
 async function request(url,body){try{const response=await fetch(url,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)}),data=await (Craft.Http?Craft.Http.json(response):response.json());if(!response.ok){const error=Error(data.error||'진화를 준비하지 못했어요.');error.status=response.status;error.resumable=response.status>=500;throw error;}return data;}catch(error){if(['TimeoutError','TypeError'].includes(error.name)){const retry=Error('진행 조회 연결이 늦어지고 있어. 같은 진화 작업을 다시 확인할 수 있어.');retry.resumable=true;throw retry;}throw error;}}
 async function wait(id,onProgress=()=>{}){if(!/^[a-f0-9]{32}$/.test(id||''))throw Error('진화 작업 형식 오류');const deadline=Date.now()+1800000;while(Date.now()<deadline){let job;for(let attempt=0;attempt<3;attempt++){try{job=await request('/api/evolution/jobs/'+id);break;}catch(error){if(!error.resumable||attempt===2)throw error;onProgress('진행 조회에 다시 연결하고 있어 · 같은 진화를 계속 준비 중');await pause(1600);}}if(job.status==='done')return job.data;if(job.status==='failed')throw Error(job.error||'진화를 완성하지 못했어요.');if(job.status==='cancelled'){const error=Error(job.message||'새 게임으로 이전 진화를 종료했어.');error.cancelled=true;throw error;}onProgress(job.message);await pause(1600);}const error=Error('진화 준비가 오래 걸리고 있어. 같은 작업을 다시 확인할 수 있어.');error.resumable=true;throw error;}
 async function artwork(src){if(!/^assets\/evolutions\/[a-f0-9]{64}-[01]\.png$/.test(src||''))throw Error('진화 이미지 형식 오류');const image=new Image();image.src=src;await image.decode();if(image.naturalWidth!==128||image.naturalHeight!==128)throw Error('진화 이미지 크기 형식 오류');const canvas=document.createElement('canvas');canvas.width=canvas.height=128;canvas.getContext('2d').drawImage(image,0,0);return canvas.toDataURL('image/png');}
 return{prepare:input=>request('/api/evolution',input),choose:(id,index)=>request('/api/evolution/jobs/'+id+'/choose',{index}),wait,artwork};
})();
